 public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri uri=r.getUrl();String path=uri.getPath();if(r.isForMainFrame()&&r.hasGesture()&&"https".equals(uri.getScheme())&&"eva.invalid".equals(uri.getHost())&&path!=null&&path.startsWith("/root/eva-workspace/")){try{String relative=path.substring("/root/eva-workspace/".length());File file=WorkspaceFiles.resolve(ShellActivity.this,relative);if(!file.isFile())throw new IOException("文件不存在或已移动");if(file.getName().toLowerCase(java.util.Locale.ROOT).matches(".*\\.(pdf|png|jpg|jpeg|webp|gif|bmp)$"))startActivity(new Intent(ShellActivity.this,WorkspacePreviewActivity.class).putExtra("path",relative));else startActivity(new Intent(ShellActivity.this,FilesActivity.class).putExtra("open-file",relative));}catch(Exception e){android.widget.Toast.makeText(ShellActivity.this,e.getMessage(),1).show();}}return true;}
