 @JavascriptInterface public boolean save(String value){long revision=saveRevision.incrementAndGet();synchronized(saveLock){return saveValue(value,revision);}}
 boolean saveValue(String value,long revision){try{if(revision!=saveRevision.get())return true;if(value.length()>2000000)return false;new JSONObject(value);return getSharedPreferences("eva-ui",0).edit().putString("state",value).commit();}catch(Exception ignored){return false;}}
 @JavascriptInterface public void saveLater(String value){long revision=saveRevision.incrementAndGet();storage.execute(()->{boolean ok;synchronized(saveLock){ok=saveValue(value,revision);}if(!ok)try{KernelHost.get(ShellActivity.this).emit(new JSONObject().put("method","android/storageError"));}catch(Exception ignored){}});}
 @JavascriptInterface public String tasks(){JSONArray result=new JSONArray();File[] list=new File(getFilesDir(),"alpine/root/eva-tasks").listFiles();if(list!=null){java.util.Arrays.sort(list,(a,b)->Long.compare(b.lastModified(),a.lastModified()));for(File f:list){try{JSONObject t=new JSONObject(new String(Files.readAllBytes(new File(f,"state.json").toPath()),"UTF-8"));JSONObject item=new JSONObject();item.put("id",f.getName());item.put("state",t.optString("state"));item.put("command",t.getJSONArray("argv").optString(2));result.put(item);}catch(Exception ignored){}}}return result.toString();}
 @JavascriptInterface public String taskDetail(String id){try{
 if(!id.matches("[a-zA-Z0-9-]{1,64}"))throw new IOException("无效任务编号");
 File folder=new File(getFilesDir(),"alpine/root/eva-tasks/"+id),file=new File(folder,"state.json");
 JSONObject t=new JSONObject(new String(Files.readAllBytes(file.toPath()),"UTF-8"));
 t.put("id",id);t.put("command",t.getJSONArray("argv").optString(2));t.put("updated",file.lastModified());t.put("errorMessage",t.optString("error"));t.remove("error");
 ByteArrayOutputStream out=new ByteArrayOutputStream(),err=new ByteArrayOutputStream();boolean truncated=t.optBoolean("outputTruncated");
 File events=new File(folder,"events.jsonl");if(events.isFile())try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(events),"UTF-8"))){String line;while((line=reader.readLine())!=null){try{JSONObject e=new JSONObject(line);if(e.optString("type").equals("output")){ByteArrayOutputStream dest=e.optString("stream").equals("stderr")?err:out;byte[] bytes=android.util.Base64.decode(e.getString("base64"),android.util.Base64.DEFAULT);int remain=131072-dest.size();dest.write(bytes,0,Math.min(remain,bytes.length));if(bytes.length>remain)truncated=true;}}catch(JSONException ignored){}}}
 t.put("stdout",out.toString("UTF-8"));t.put("stderr",err.toString("UTF-8"));t.put("truncated",truncated);return t.toString();
 }catch(Exception e){try{return new JSONObject().put("error",e.getMessage()).toString();}catch(Exception ignored){return "{}";}}}
 @JavascriptInterface public void open(String kind){runOnUiThread(()->{if(kind.equals("office-runtime")){startActivity(new Intent(ShellActivity.this,OfficeActivity.class));return;}if(kind.equals("data-backup")){startActivity(new Intent(ShellActivity.this,DataBackupActivity.class));return;}if(kind.equals("voice")){startActivity(new Intent(ShellActivity.this,VoiceActivity.class));return;}if(kind.equals("phone-control")){startActivity(new Intent(ShellActivity.this,PhoneControlActivity.class));return;}if(kind.equals("account")){startActivity(new Intent(ShellActivity.this,AccountActivity.class));return;}if(kind.equals("models")){startActivity(new Intent(ShellActivity.this,ModelsActivity.class));return;}if(kind.equals("settings")){web.evaluateJavascript("settingsGo('settings')",null);return;}if(kind.equals("app-settings")){startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));return;}if(kind.equals("diagnostics")){startActivity(new Intent(ShellActivity.this,MainActivity.class));return;}if(kind.equals("tools")){new AlertDialog.Builder(ShellActivity.this).setTitle("此手机工具").setItems(new String[]{"本地终端","工作区","Eva 浏览器"},(d,n)->open(new String[]{"terminal","files","browser"}[n])).show();return;}if(kind.equals("browser")){showBrowser(new Intent());return;}if(kind.equals("terminal")||kind.equals("files")){Intent intent=new Intent(ShellActivity.this,kind.equals("terminal")?TerminalActivity.class:FilesActivity.class);startActivity(intent);}});}
